package cn.reviewsystem.mastery;

import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest
class MasteryEventIntegrationTest {
 @Autowired JdbcTemplate db;@Autowired MasteryEventConsumer consumer;@Autowired MasteryController controller;
 long user,chapter,k1,k2,q1,q2,v1,v2;List<Long> practices=new ArrayList<>();String prefix="m05"+UUID.randomUUID().toString().replace("-","").substring(0,9);
 @BeforeEach void setup(){user=db.queryForObject("INSERT INTO rs_user(username,password_hash,role) VALUES (?,'test','STUDENT') RETURNING id",Long.class,prefix);chapter=db.queryForObject("INSERT INTO rs_chapter(subject_id,code,name,sort_order) VALUES (1,?,?,1) RETURNING id",Long.class,prefix.substring(0,8),prefix);k1=knowledge("A");k2=knowledge("B");q1=question("A");q2=question("B");v1=version(q1,k1,1);v2=version(q2,k2,1);}
 long knowledge(String suffix){return db.queryForObject("INSERT INTO rs_knowledge_point(subject_id,chapter_id,code,name,sort_order) VALUES (1,?,?,?,1) RETURNING id",Long.class,chapter,prefix+suffix,prefix+suffix);}
 long question(String suffix){return db.queryForObject("INSERT INTO rs_question(subject_id,question_no,origin,status) VALUES (1,?,'MANUAL','ACTIVE') RETURNING id",Long.class,prefix+suffix);}
 long version(long q,long k,int number){long v=db.queryForObject("INSERT INTO rs_question_version(question_id,version,subject_id,knowledge_point_id,type,max_score,content_json,answer_json) VALUES (?,?,1,?,'CHOICE',1,'{}','{}') RETURNING id",Long.class,q,number,k);db.update("UPDATE rs_question SET current_version_id=? WHERE id=?",v,q);return v;}
 long practice(long q,long v,long k){long activity=db.queryForObject("INSERT INTO rs_learning_activity(user_id,subject_id,kind,status) VALUES (?,1,'PRACTICE','COMPLETED') RETURNING id",Long.class,user);long p=db.queryForObject("INSERT INTO rs_practice(activity_id,user_id,subject_id,question_count,mix_ratio_json,request_key,submitted_at) VALUES (?,?,1,1,'{}',?,CURRENT_TIMESTAMP) RETURNING id",Long.class,activity,user,prefix+UUID.randomUUID());practices.add(p);db.update("INSERT INTO rs_practice_item(practice_id,question_id,question_version_id,knowledge_id,question_type,max_score,position,result_json,grading_status) VALUES (?,?,?,?,'CHOICE',1,0,'{\"passed\":true}','AUTO_GRADED')",p,q,v,k);return p;}
 long event(long p){return db.queryForObject("INSERT INTO rs_change_event(event_type,source_id,source_revision,state) VALUES ('PRACTICE_SUBMITTED',?,1,'PENDING') RETURNING id",Long.class,p);}
 long count(String table){return db.queryForObject("SELECT count(*) FROM "+table+" WHERE user_id=?",Long.class,user);}
 @AfterEach void clean(){for(long p:practices)db.update("DELETE FROM rs_change_event WHERE source_id=?",p);db.update("DELETE FROM rs_mastery_current WHERE user_id=?",user);db.update("DELETE FROM rs_mastery_snapshot WHERE user_id=?",user);db.update("DELETE FROM rs_evidence WHERE user_id=?",user);db.update("DELETE FROM rs_student_course_guard WHERE user_id=?",user);for(long p:practices){db.update("DELETE FROM rs_practice_item WHERE practice_id=?",p);db.update("DELETE FROM rs_practice WHERE id=?",p);}db.update("DELETE FROM rs_learning_activity WHERE user_id=?",user);for(long q:List.of(q1,q2)){db.update("UPDATE rs_question SET current_version_id=NULL WHERE id=?",q);db.update("DELETE FROM rs_question_version WHERE question_id=?",q);db.update("DELETE FROM rs_question WHERE id=?",q);}db.update("DELETE FROM rs_knowledge_point WHERE chapter_id=?",chapter);db.update("DELETE FROM rs_chapter WHERE id=?",chapter);db.update("DELETE FROM rs_user WHERE id=?",user);}
 @Test void sameEventTwiceKeepsEvidenceSnapshotAndRevisionUnique(){long p=practice(q1,v1,k1);event(p);assertTrue(consumer.processNext());assertFalse(consumer.processNext());assertEquals(1,count("rs_evidence"),db.queryForObject("SELECT last_error FROM rs_change_event WHERE source_id=?",String.class,p));assertEquals(1,count("rs_mastery_snapshot"));/* This fixture inserts the event directly, so submit never increments the guard. */assertEquals(0L,db.queryForObject("SELECT learning_revision FROM rs_student_course_guard WHERE user_id=? AND subject_id=1",Long.class,user));}
 @Test void failedEventRetriesAndStoresRootCause(){long missing=987654321L;long id=event(missing);assertTrue(consumer.processNext());assertEquals("FAILED",db.queryForObject("SELECT state FROM rs_change_event WHERE id=?",String.class,id));assertNotNull(db.queryForObject("SELECT last_error FROM rs_change_event WHERE id=?",String.class,id));long p=practice(q1,v1,k1);db.update("UPDATE rs_change_event SET source_id=?,next_retry_at=CURRENT_TIMESTAMP WHERE id=?",p,id);assertTrue(consumer.processNext());assertEquals("DONE",db.queryForObject("SELECT state FROM rs_change_event WHERE id=?",String.class,id));}
 @Test void rebindingKeepsOldEvidenceOnOldKnowledge(){long first=practice(q1,v1,k1);event(first);consumer.processNext();long secondVersion=version(q1,k2,2);long second=practice(q1,secondVersion,k2);event(second);consumer.processNext();assertEquals(1L,db.queryForObject("SELECT count(*) FROM rs_evidence WHERE user_id=? AND knowledge_id=?",Long.class,user,k1));assertEquals(1L,db.queryForObject("SELECT count(*) FROM rs_evidence WHERE user_id=? AND knowledge_id=?",Long.class,user,k2));}
 @Test void concurrentEventsKeepBothKnowledgePointers()throws Exception {long first=practice(q1,v1,k1),second=practice(q2,v2,k2);event(first);event(second);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var a=pool.submit(consumer::processNext);var b=pool.submit(consumer::processNext);a.get(10,TimeUnit.SECONDS);b.get(10,TimeUnit.SECONDS);}consumer.processNext();assertEquals(2,count("rs_evidence"));assertEquals(2,count("rs_mastery_current"));/* Both events bypass submit; consumption must leave learning_revision at its default. */assertEquals(0L,db.queryForObject("SELECT learning_revision FROM rs_student_course_guard WHERE user_id=? AND subject_id=1",Long.class,user));}
 @Test void olderEventCannotOverwriteNewerSubjectiveEvidence(){long p=practice(q1,v1,k1);db.update("INSERT INTO rs_evidence(user_id,source_type,submission_id,question_id,question_version_id,knowledge_id,question_type,result_y,weight,source_revision,submitted_at,graded_at) VALUES (?,'PRACTICE',?,?,?,?,? ,0.8,0.60,2,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",user,p,q1,v1,k1,"ALGORITHM");event(p);assertTrue(consumer.processNext());var evidence=db.queryForMap("SELECT result_y,weight,source_revision,question_type FROM rs_evidence WHERE source_type='PRACTICE' AND submission_id=? AND question_id=?",p,q1);assertEquals(0,new java.math.BigDecimal("0.8").compareTo((java.math.BigDecimal)evidence.get("result_y")));assertEquals(0,new java.math.BigDecimal("0.60").compareTo((java.math.BigDecimal)evidence.get("weight")));assertEquals(2,evidence.get("source_revision"));assertEquals("ALGORITHM",evidence.get("question_type"));assertEquals(1,count("rs_evidence"));}
 @Test void historyEvidenceBatchQueryPreservesSelectedOrderAndValues(){long first=practice(q1,v1,k1);event(first);consumer.processNext();long second=practice(q2,v2,k2);event(second);consumer.processNext();long firstId=db.queryForObject("SELECT id FROM rs_evidence WHERE submission_id=?",Long.class,first),secondId=db.queryForObject("SELECT id FROM rs_evidence WHERE submission_id=?",Long.class,second);var ordered=controller.evidence("["+secondId+","+firstId+"]",user);assertEquals(2,ordered.size());assertEquals(prefix+"B",ordered.get(0).questionNo());assertEquals(prefix+"A",ordered.get(1).questionNo());for(var row:ordered){assertEquals("CHOICE",row.questionType());assertEquals(0,new java.math.BigDecimal("1.00").compareTo(row.weight()));assertEquals(0,java.math.BigDecimal.ONE.compareTo(row.resultY()));assertNotNull(row.submittedAt());}}
 @Test void revokedLatestEvidenceFallsBackToPreviousValidAttempt(){long old=practice(q1,v1,k1);event(old);consumer.processNext();long latest=practice(q1,v1,k1);db.update("UPDATE rs_practice_item SET result_json='{\"passed\":false}' WHERE practice_id=?",latest);event(latest);consumer.processNext();db.update("UPDATE rs_evidence SET revoked=TRUE WHERE submission_id=?",latest);consumer.recalculate(user,k1);assertEquals(1L,db.queryForObject("SELECT n FROM rs_mastery_snapshot WHERE id=(SELECT snapshot_id FROM rs_mastery_current WHERE user_id=? AND knowledge_id=?)",Long.class,user,k1));assertEquals(1,db.queryForObject("SELECT weighted_sum FROM rs_mastery_snapshot WHERE id=(SELECT snapshot_id FROM rs_mastery_current WHERE user_id=? AND knowledge_id=?)",java.math.BigDecimal.class,user,k1).intValue());}
}
